  const analysisTypes = analysis ?? ['tree_shaking', 'duplicate_deps', 'large_modules'];

  if (analysisTypes.includes('duplicate_deps')) {
    optimizations.push({
      id: 'bo-1',
      type: 'duplicate_deps',
      severity: 'high',
      target: 'lodash',
