export const ConfigOptimizeInputSchema = z.object({
  workloadProfile: z.object({
    type: z.enum(['web', 'api', 'batch', 'stream', 'hybrid']),
    metrics: z.object({
      requestsPerSecond: z.number().min(0).optional(),
      avgResponseTime: z.number().min(0).optional(),
