describe('PerfFpgaBridge', () => {
  let bridge: PerfFpgaBridge;

  beforeEach(() => {
    bridge = createPerfFpgaBridge();
  });

  afterEach(async () => {
    await bridge.destroy();
  });

  describe('initialization', () => {
    it('should start in unloaded state', () => {
      expect(bridge.isReady()).toBe(false);
    });

